INSERT INTO suppliers (client_id, name, notes, position) SELECT 1, 'GFS (Gordon Food Service)', 'Fournisseur principal pour l’instant (peut changer bientôt)', 1 WHERE NOT EXISTS (SELECT 1 FROM suppliers WHERE client_id = 1);
INSERT INTO suppliers (client_id, name, notes, position) SELECT 1, 'Duval (Duval Fruits et Légumes)', 'Fruits et légumes', 2 WHERE (SELECT COUNT(*) FROM suppliers WHERE client_id = 1) = 1 AND EXISTS (SELECT 1 FROM suppliers WHERE client_id = 1 AND name = 'GFS (Gordon Food Service)');
